#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct LexicographicSplit {
    pub strict_taken: bool,
    pub non_increasing: Rc<Vec<Rc<RankingDimension>>>,
}

pub fn non_strict_dimensions_after_first(
    rows: Rc<Vec<Rc<MeasureDimensionEvidence>>>,
) -> Rc<Vec<Rc<RankingDimension>>> {
    {
        let split = rows.clone().iter().cloned().fold(
            Rc::new(LexicographicSplit {
                strict_taken: false,
                non_increasing: Rc::new(vec![]),
            }),
            |acc: _, row: _| {
                if (dimension_row_is_strict(row.clone()) && !acc.strict_taken.clone()) {
                    Rc::new(LexicographicSplit {
                        strict_taken: true,
                        non_increasing: acc.non_increasing.clone(),
                    })
                } else {
                    Rc::new(LexicographicSplit {
                        strict_taken: acc.strict_taken.clone(),
                        non_increasing: Rc::new({
                            let mut __cons_v = (*acc.non_increasing.clone()).clone();
                            __cons_v.insert(0, row.dimension.clone());
                            __cons_v
                        }),
                    })
                }
            },
        );
        split.non_increasing.clone()
    }
}

pub fn lexicographic_multiplicity(rows: Rc<Vec<Rc<MeasureDimensionEvidence>>>) -> Rc<Multiplicity> {
    match first_strict_dimension(rows.clone()) {
        None => Rc::new(Multiplicity::RequiresTerminationProof),
        Some(strict_dim) => Rc::new(Multiplicity::ProvenTermination {
            proof: Rc::new(TerminationProof {
                non_increasing: non_strict_dimensions_after_first(rows.clone()),
                strict: strict_dim.clone(),
            }),
        }),
    }
}

pub fn loop_multiplicity_from_rows(
    rows: Rc<Vec<Rc<MeasureDimensionEvidence>>>,
) -> Rc<Multiplicity> {
    if ((rows.clone().len() as i64) == 0) {
        Rc::new(Multiplicity::RequiresTerminationProof)
    } else {
        match dimension_rows_meet(rows.clone()) {
            DescentEvidence::DescentUnknown => Rc::new(Multiplicity::RequiresTerminationProof),
            DescentEvidence::NonIncreasing => lexicographic_multiplicity(rows.clone()),
            DescentEvidence::Strict => lexicographic_multiplicity(rows.clone()),
        }
    }
}

